#!/usr/bin/env bash
set -u
umask 077

app=/usr/local/lib/hrules-six/hrules-six.py
manager=/usr/local/sbin/hrules-six
state=/var/lib/hrules-six/state.json
landing_state=/var/lib/hrules-six/landing/state.json
core=hrules-six-mihomo.service
subscription=hrules-six-subscription.service
timer=hrules-six-traffic.timer
timer_file=/etc/systemd/system/$timer
shortcut_dir=/usr/local/bin
shortcut_record=/var/lib/hrules-six/menu-shortcut
incoming=
title_color=
accent=
dim=
plain=
success=
warning=
failure=
if [[ -t 1 && ${TERM:-dumb} != dumb && -z ${NO_COLOR:-} ]]; then
    title_color=$'\033[1;36m'
    accent=$'\033[36m'
    dim=$'\033[2m'
    plain=$'\033[0m'
    success=$'\033[32m'
    warning=$'\033[33m'
    failure=$'\033[31m'
fi

cleanup() {
    if [[ -n $incoming ]]; then
        rm -f -- "$incoming"
    fi
}
trap cleanup EXIT

usage() {
    printf '%s\n' '用法  sudo bash hrules-six.sh [install|uninstall|landing|node-prefix|status|diagnose|links|quota|traffic-interval|outbound|nodes|shortcut|update|performance|bbr3|system-update|system-info|security-updates|ssh-key|ssh-defense|ssh-update|firewall|firewall-ports|reality-vision] [选项]'
    printf '%s\n' '无参数打开管理菜单。首次打开后默认用 m 快捷启动。'
}

if [[ ${1:-} == -h || ${1:-} == --help ]]; then
    usage
    exit 0
fi

self=$(readlink -f -- "${BASH_SOURCE[0]}") || exit 1
if [[ $EUID -ne 0 ]]; then
    if command -v sudo >/dev/null 2>&1; then
        exec sudo -- bash "$self" "$@"
    fi
    printf '%s\n' '请用 root 账号运行。' >&2
    exit 1
fi

backend_ready() {
    if [[ ! -f $state || ! -f $app ]]; then
        printf '%s\n' '请先选择 1 安装。' >&2
        return 1
    fi
}

traffic_ready() {
    backend_ready || return 1
    local help
    if [[ -f $timer_file ]] && help=$(python3 "$app" --help 2>/dev/null) &&
        [[ $help == *',quota,'* && $help == *',traffic-interval,'* ]]; then
        return 0
    fi
    printf '\n%s\n' '当前 VPS 仍在使用旧版服务程序。' \
        '请返回菜单，选择 1. 安装 / 更新协议服务。' >&2
    printf '\n也可在 SSH 终端执行以下命令更新。\n  sudo bash %q install\n' "$self" >&2
    return 1
}

run_backend() {
    case $1 in
        quota|traffic-interval) traffic_ready || return 1 ;;
        outbound|nodes)
            backend_ready || return 1
            local help command=$1
            if ! help=$(python3 "$app" --help 2>/dev/null) || [[ $help != *",$command,"* ]]; then
                printf '%s\n' '当前 VPS 的服务程序需更新。请返回菜单选择 1. 安装 / 更新协议服务。' >&2
                return 1
            fi
            ;;
        *) backend_ready || return 1 ;;
    esac
    python3 "$app" "$@"
}

extract_backend() {
    if ! command -v python3 >/dev/null 2>&1; then
        printf '%s\n' '正在安装 Python 3。'
        apt-get update && apt-get install -y python3 || return 1
    fi
    incoming=$(mktemp /tmp/hrules-six-backend.XXXXXXXX.py) || return 1
    if ! python3 - "$self" "$incoming" <<'PY'
import base64
import binascii
import gzip
import hashlib
from pathlib import Path
import sys
import zlib

if sys.version_info < (3, 9):
    sys.exit("需要 Python 3.9 或以上。")

source = Path(sys.argv[1]).read_bytes()
_, separator, payload = source.partition(b"\n__HRULES_BACKEND_V1__\n")
lines = payload.splitlines()
if not separator or len(lines) != 3 or lines[-1] != b"__HRULES_BACKEND_END__":
    sys.exit("安装程序格式不完整。请重新下载并上传 hrules-six.sh。")
digest, data, _ = lines
try:
    backend = gzip.decompress(base64.b64decode(data, validate=True))
except (binascii.Error, EOFError, OSError, zlib.error):
    sys.exit("安装程序数据损坏。请重新下载并上传 hrules-six.sh。")
if hashlib.sha256(backend).hexdigest().encode("ascii") != digest:
    sys.exit("安装程序校验失败。请重新下载完整的 hrules-six.sh。")
Path(sys.argv[2]).write_bytes(backend)
PY
    then
        cleanup
        incoming=
        return 1
    fi
}

create_command_directory() (
    umask 022
    mkdir -p -- "$1"
)

initialize_manager_updates() {
    local setup=${state%/*}/github-auto-update-setup
    if [[ ! -f $setup || $(<"$setup") != configured ]]; then
        if ! run_installer update --update-action init-auto >/dev/null; then
            printf '%s\n' '自动更新初始化未完成，下次打开脚本时会重试。' >&2
        fi
    fi
}

install_manager() {
    local pending
    if [[ -x $manager ]] && cmp -s -- "$self" "$manager"; then
        initialize_manager_updates
        return
    fi
    create_command_directory "${manager%/*}" || return 1
    pending=$(mktemp "${manager}.XXXXXXXX") || return 1
    if ! install -m 0755 -- "$self" "$pending" || ! mv -fT -- "$pending" "$manager"; then
        rm -f -- "$pending"
        return 1
    fi
    initialize_manager_updates
}

ensure_manager() {
    if [[ -x $manager ]]; then
        initialize_manager_updates
    else
        install_manager
    fi
}

run_installer() {
    local action=$1
    shift
    extract_backend || return 1
    local rc=0
    python3 "$incoming" "$action" "$@" || rc=$?
    cleanup
    incoming=
    if (( rc == 3 )) && [[ $action == install ]]; then
        return 0
    fi
    if (( rc == 0 )) && [[ $action == install || $action == node-prefix || ( $action == landing && -f $landing_state ) ]]; then
        install_manager || return 1
        printf '\n%s\n' '命令行输入 sudo hrules-six 可重新打开菜单。'
    fi
    return "$rc"
}

install_stack() {
    if [[ $self == "${state%/*}"/hrules-update-*/hrules-six.sh ]]; then
        HRULES_KEEP_FIREWALL=1 run_installer install "$@"
    else
        run_installer install "$@"
    fi
}

edit_node_prefix() {
    backend_ready || return 1
    local help
    if ! help=$(python3 "$app" --help 2>/dev/null) || [[ $help != *'--node-suffix'* ]]; then
        printf '当前 VPS 服务程序需要先升级一次。请运行 sudo bash %q install，再使用菜单 1 → 4。\n' "$self" >&2
        return 1
    fi
    run_installer node-prefix "$@"
}

draw_install_menu() {
    menu_title '安装 / 更新协议服务'
    menu_heading '安装方式'
    menu_item 1 '安装推荐协议'
    menu_note 'IPv4 / 双栈 9 项，IPv6 单栈 2 项'
    menu_item 2 '自选安装协议'
    menu_note '多选时用空格分隔序号'
    menu_item 3 '独立 Shadowsocks 落地'
    menu_note '仅生成供入口 VPS 使用的独立链接'

    menu_heading '节点设置'
    menu_item 4 '自定义节点名称前缀'
    menu_item 5 '协议节点管理'
    menu_note '启停节点或更换监听端口'
    menu_item 6 'IPv6 节点部署'
    menu_note '按协议设置仅 IPv6 或双栈入口'
    menu_item 0 '返回主菜单'
}

guided_install() {
    local choice
    while true; do
        draw_install_menu
        menu_prompt '请选择 [0–6]' choice || return 0
        case $choice in
            1) install_stack --profile recommended || : ;;
            2) install_stack --profile custom || : ;;
            3) run_installer landing || :; continue ;;
            4) edit_node_prefix || : ;;
            5) run_backend nodes || :; continue ;;
            6) run_backend nodes --ipv6-entries || :; continue ;;
            0|'') return 0 ;;
            *) printf '%s\n' '请输入 0–6。'; continue ;;
        esac
        menu_prompt '按 Enter 返回安装与节点管理' _ || return 0
    done
}

show_services() {
    backend_ready || return 1
    local service status label color
    menu_title '服务状态'
    printf '  %s%s%s    %s%s%s\n' "$accent" '服务    ' "$plain" "$accent" '状态' "$plain"
    for service in "$core" "$subscription" "$timer"; do
        case $service in
            "$core") label='代理服务' ;;
            "$subscription") label='订阅服务' ;;
            "$timer") label='流量采样' ;;
        esac
        status=$(systemctl is-active "$service" 2>/dev/null) || :
        color=${warning:-}
        case $status in
            active) status='运行中'; color=${success:-} ;;
            inactive) status='已停止' ;;
            failed) status='故障'; color=${failure:-} ;;
            activating) status='启动中' ;;
            deactivating) status='停止中' ;;
            *) status='未就绪' ;;
        esac
        printf '  %s    %s%s%s\n' "$label" "$color" "$status" "$plain"
    done
    run_backend quota
}

ask_limit() {
    traffic_ready || return 1
    local limit
    menu_prompt '输入新的共享上限（GiB，0 为不限额，留空返回）' limit || return 1
    if [[ -n $limit ]]; then
        python3 "$app" quota --limit-gb "$limit"
    fi
}

ask_reset() {
    traffic_ready || return 1
    local answer
    menu_prompt '输入 RESET 清零累计流量' answer || return 1
    if [[ $answer == RESET ]]; then
        python3 "$app" quota --reset
    fi
}

ask_interval() {
    local seconds
    run_backend traffic-interval || return 1
    menu_prompt '采样间隔（5 / 15 / 30 / 60 秒，留空返回）' seconds || return 1
    if [[ -n $seconds ]]; then
        run_backend traffic-interval --seconds "$seconds"
    fi
}

ask_hop() {
    backend_ready || return 1
    local answer ports interval
    local -a options
    menu_prompt '启用 Hysteria2 端口跳跃？[y/n，留空返回]' answer || return 1
    case ${answer,,} in
        y|yes)
            menu_prompt '附加 UDP 范围 [24000-24015]' ports || return 1
            menu_prompt '跳跃间隔（秒，如 30 或 15-45，留空沿用）' interval || return 1
            options=(--hysteria2-hop-ports "${ports:-24000-24015}")
            if [[ -n $interval ]]; then
                options+=(--hysteria2-hop-interval "$interval")
            fi
            install_stack --yes "${options[@]}"
            ;;
        n|no) install_stack --yes --hysteria2-hop-ports none ;;
        '') return 0 ;;
        *) printf '%s\n' '请输入 y 或 n。' >&2; return 1 ;;
    esac
}

guided_hysteria() {
    backend_ready || return 1
    local choice
    while true; do
        menu_title 'Hysteria2 设置'
        menu_heading '连接参数'
        menu_item 1 '设置 / 关闭端口跳跃'
        menu_item 2 '设置上传 / 下载速率'
        menu_item 3 '恢复速率调整前的设置'
        menu_heading '传输参数'
        menu_item 4 'Salamander 混淆'
        menu_item 5 'QUIC 参数'
        menu_item 6 'HTTP / TLS / QUIC 嗅探'
        menu_item 7 '检查 UDP 跳跃转发'
        menu_item 0 '返回主菜单'
        menu_prompt '请选择 [0–7]' choice || return 0
        case $choice in
            1) ask_hop || : ;;
            2) run_installer performance --performance-action hysteria || : ;;
            3) run_installer performance --performance-action hysteria-restore || : ;;
            4) run_installer hysteria-settings --hysteria-action obfs || : ;;
            5) run_installer hysteria-settings --hysteria-action quic || : ;;
            6) run_installer hysteria-settings --hysteria-action sniff || : ;;
            7) run_installer hysteria-settings --hysteria-action hop-status || : ;;
            0|'') return 0 ;;
            *) printf '%s\n' '请输入 0–7。'; continue ;;
        esac
        menu_prompt '按 Enter 返回 Hysteria2 设置' _ || return 0
    done
}

valid_shortcut() {
    [[ $1 =~ ^[a-zA-Z][a-zA-Z0-9_-]{0,15}$ ]]
}

shortcut_script() {
    printf '#!/usr/bin/env bash\nexec %q "$@"\n' "$manager"
}

shortcut_taken() {
    [[ -e $shortcut_dir/$1 || -L $shortcut_dir/$1 ]] || command -v -- "$1" >/dev/null 2>&1
}

get_shortcut() {
    local key
    [[ -f $shortcut_record ]] || return 0
    IFS= read -r key < "$shortcut_record" || return 0
    valid_shortcut "$key" || return 0
    [[ -f $shortcut_dir/$key && ! -L $shortcut_dir/$key ]] || return 0
    cmp -s -- "$shortcut_dir/$key" <(shortcut_script) || return 0
    printf '%s\n' "$key"
}

shortcut_command() {
    local key=${1:-} old target pending launcher
    old=$(get_shortcut)
    if [[ -z $key ]]; then
        printf '当前快捷命令  %s\n' "${old:-未设置}"
        return 0
    fi
    if [[ $key == --remove ]]; then
        mkdir -p -- "${shortcut_record%/*}" || return 1
        pending=$(mktemp "${shortcut_record}.XXXXXXXX") || return 1
        if ! printf '\n' > "$pending" || ! mv -fT -- "$pending" "$shortcut_record"; then
            rm -f -- "$pending"
            return 1
        fi
        if [[ -n $old ]]; then
            rm -- "$shortcut_dir/$old" || return 1
        fi
        printf '%s\n' '已取消快捷启动。'
        return 0
    fi
    if ! valid_shortcut "$key" || [[ $key == hrules-six ]]; then
        printf '%s\n' '请输入 1–16 个英文字母、数字、下划线或连字符，首字符用英文字母。' >&2
        return 1
    fi
    if [[ $key == "$old" ]]; then
        ensure_manager || return 1
        printf '已设置  输入 %s 回车打开菜单。\n' "$key"
        return 0
    fi
    target="$shortcut_dir/$key"
    if shortcut_taken "$key"; then
        printf '快捷命令 %s 已被占用，请换一个名称。\n' "$key" >&2
        return 1
    fi
    ensure_manager || return 1
    create_command_directory "$shortcut_dir" || return 1
    mkdir -p -- "${shortcut_record%/*}" || return 1
    pending=$(mktemp "${shortcut_record}.XXXXXXXX") || return 1
    launcher=$(mktemp "$shortcut_dir/.hrules-launcher.XXXXXXXX") || {
        rm -f -- "$pending"
        return 1
    }
    if ! printf '%s\n' "$key" > "$pending" || ! shortcut_script > "$launcher" ||
        ! chmod 0755 -- "$launcher" || ! ln -T -- "$launcher" "$target"; then
        rm -f -- "$pending" "$launcher"
        return 1
    fi
    rm -f -- "$launcher"
    if ! mv -fT -- "$pending" "$shortcut_record"; then
        rm -f -- "$pending" "$target"
        return 1
    fi
    if [[ -n $old ]]; then
        rm -- "$shortcut_dir/$old" || return 1
    fi
    printf '已设置  输入 %s 回车打开菜单。\n' "$key"
}

initialize_menu_shortcut() {
    if ! ensure_manager; then
        printf '%s\n' '菜单启动文件写入失败，可在菜单 17 重试。' >&2
    elif [[ ! -e $shortcut_record && ! -L $shortcut_record ]]; then
        shortcut_command m || printf '%s\n' '可在菜单 17 设置快捷命令。' >&2
    fi
}

ask_shortcut() {
    local key
    shortcut_command || return 1
    printf '%s\n' '例如输入 m，之后在 SSH 终端输入 m 并回车。'
    menu_prompt '输入快捷命令（输入 - 取消，留空返回）' key || return 1
    case $key in
        '') return 0 ;;
        -) shortcut_command --remove ;;
        *) shortcut_command "$key" ;;
    esac
}

menu_heading() {
    printf '\n  %s%s%s\n' "$title_color" "$1" "$plain"
}

menu_title() {
    printf '\n%s%s%s\n%s%s%s\n' "$title_color" "$1" "$plain" \
        "$dim" '────────────────────────────────────────' "$plain"
}

menu_item() {
    local color=${3:-$accent}
    if [[ $1 == 0 ]]; then
        printf '\n'
        color=$dim
    fi
    printf '  %s%2s%s  %s\n' "$color" "$1" "$plain" "$2"
}

menu_note() {
    printf '      %s%s%s\n' "$dim" "$1" "$plain"
}

menu_prompt() {
    read -r -p $'\n'"${accent}$1${plain}  " "$2"
}

menu_message() {
    printf '%s%s%s\n' "$2" "$1" "$plain"
}

guided_firewall() {
    local choice
    menu_title '防火墙管理'
    menu_item 1 '一键启用 UFW'
    menu_item 2 '一键启用 firewalld（推荐）'
    menu_item 3 '查看放行端口'
    menu_item 0 '返回上一级'
    menu_prompt '请选择 [0–3]' choice || return 0
    case $choice in
        1) run_installer firewall --firewall-backend ufw ;;
        2) run_installer firewall --firewall-backend firewalld ;;
        3) run_installer firewall-ports ;;
        0|'') return 0 ;;
        *) menu_message '请选择菜单上的数字。' "${warning:-}" ;;
    esac
    return 1
}

guided_auto_update() {
    local window detection
    menu_prompt '更新时段 HH:MM-HH:MM（回车 02:00-02:59，输入 0 关闭）' window || return 0
    if [[ $window != 0 ]]; then
        menu_prompt '检测间隔小时数或每日 HH:MM（回车 24 小时）' detection || return 0
    fi
    run_installer update --update-action configure-auto --update-time "${window:-default}" \
        --update-check "${detection:-24}"
}

apply_menu_update() {
    local action=$1 running installed
    running=$(sha256sum -- "$self") || return 1
    run_installer update --update-action "$action" || return $?
    [[ -x $manager ]] || return 0
    installed=$(sha256sum -- "$manager") || return 1
    if [[ ${running%% *} != "${installed%% *}" ]]; then
        menu_prompt '按 Enter 返回主菜单' _ || return 0
        exec bash "$manager" menu
    fi
}

guided_update() {
    local choice
    while true; do
        menu_title '脚本维护'
        run_installer update --update-action status || return 1
        printf '\n'
        menu_item 1 '自动更新设置'
        menu_item 2 '恢复上一版'
        menu_item 3 '关闭自动更新'
        menu_item 4 '一键卸载 Hrules' "${warning:-}"
        menu_note '停止服务并删除节点、订阅和流量记录'
        menu_item 0 '返回主菜单'
        printf '\n%s%s%s\n%s\n' "$accent" '在线安装命令' "$plain" \
            'bash <(curl -fsSL https://raw.githubusercontent.com/SUYUEM/Hrules-install/main/install.sh)'
        menu_prompt '请选择 [0–4]' choice || return 0
        case $choice in
            1) guided_auto_update || : ;;
            2) apply_menu_update rollback || : ;;
            3) run_installer update --update-action configure-auto --update-time 0 --update-check 24 || : ;;
            4) run_installer uninstall && exit 0 ;;
            0|'') return 0 ;;
            *) menu_message '请选择菜单上的数字。' "${warning:-}"; continue ;;
        esac
        menu_prompt '按 Enter 返回脚本维护' _ || return 0
    done
}

guided_performance() {
    local choice
    while true; do
        menu_title '节点测速与基准'
        menu_item 1 '测速并保存基准'
        menu_item 2 '复测并对比已有基准'
        menu_item 3 '查看 Windows 客户端测速命令'
        menu_item 0 '返回主菜单'
        menu_prompt '请选择 [0–3]' choice || return 0
        case $choice in
            1) run_installer performance --performance-action baseline || : ;;
            2) run_installer performance --performance-action compare || : ;;
            3) run_installer performance --performance-action windows || : ;;
            0|'') return 0 ;;
            *) menu_message '请选择菜单上的数字。' "${warning:-}"; continue ;;
        esac
        menu_prompt '按 Enter 返回节点测速' _ || return 0
    done
}

guided_bbr3() {
    local choice
    while true; do
        menu_title 'TCP / BBRv3 设置'
        run_installer bbr3 --bbr-status || return 1
        printf '\n'
        menu_item 1 '安装 / 更新 BBRv3 内核'
        menu_item 2 '启用 TCP BBR / fq'
        menu_item 3 '恢复 TCP 调优前参数'
        menu_item 0 '返回主菜单'
        menu_prompt '请选择 [0–3]' choice || return 0
        case $choice in
            1) run_installer bbr3 --bbr-update --yes || : ;;
            2) run_installer performance --performance-action tcp || : ;;
            3) run_installer performance --performance-action tcp-restore || : ;;
            0|'') return 0 ;;
            *) menu_message '请选择菜单上的数字。' "${warning:-}"; continue ;;
        esac
        menu_prompt '按 Enter 返回 TCP / BBRv3 设置' _ || return 0
    done
}

guided_ssh_defense() {
    local choice action
    while true; do
        menu_title 'SSH 防御（Fail2Ban）'
        run_installer ssh-defense --ssh-action summary || return 1
        printf '\n'
        menu_item 1 '安装 / 启用防御'
        menu_item 2 '查看 SSH 封禁'
        menu_item 3 '实时日志（Ctrl+C 返回）'
        menu_item 4 '设置封禁参数'
        menu_item 5 '编辑防御配置'
        menu_item 9 '移除 Hrules SSH 防御' "${warning:-}"
        menu_item 0 '返回上一级'
        menu_prompt '请选择 [0–5、9]' choice || return 0
        case $choice in
            1) action=install ;;
            2) action=status ;;
            3) action=logs ;;
            4) action=configure ;;
            5) action=edit ;;
            9) action=remove ;;
            0) return 0 ;;
            '') continue ;;
            *) menu_message '请选择菜单上的数字。' "${warning:-}"; continue ;;
        esac
        printf '\n'
        if run_installer ssh-defense --ssh-action "$action" && [[ $action != logs ]]; then
            menu_message '操作完成' "${success:-}"
        fi
        menu_prompt '按 Enter 返回 SSH 防御菜单' _ || return 0
    done
}

guided_ssh_keys() {
    local choice action
    while true; do
        menu_title 'SSH 密钥登录'
        menu_item 1 '生成新密钥对'
        menu_item 2 '手动输入已有公钥'
        menu_item 3 '自检 SSH 登录方式'
        menu_item 4 '切换回密码登录' "${warning:-}"
        menu_item 0 '返回系统安全加固'
        menu_prompt '请选择 [0–4]' choice || return 0
        case $choice in
            1) action=generate ;;
            2) action=import ;;
            3) action=status ;;
            4) action=password ;;
            0|'') return 0 ;;
            *) menu_message '请选择菜单上的数字。' "${warning:-}"; continue ;;
        esac
        run_installer ssh-key --ssh-key-action "$action" || :
        menu_prompt '按 Enter 返回 SSH 密钥登录' _ || return 0
    done
}

guided_system_security() {
    local choice
    while true; do
        menu_title '系统安全加固'
        menu_item 1 'SSH 密钥登录'
        menu_item 2 'SSH 防御（Fail2Ban）'
        menu_item 3 '防火墙管理'
        menu_item 4 '启用系统安全补丁自动更新'
        menu_item 5 'OpenSSH（安全漏洞修复）'
        menu_item 0 '返回主菜单'
        menu_prompt '请选择 [0–5]' choice || return 0
        case $choice in
            1) guided_ssh_keys; continue ;;
            2) guided_ssh_defense || :; continue ;;
            3) if guided_firewall; then continue; fi ;;
            4) run_installer security-updates || : ;;
            5) run_installer ssh-update || : ;;
            0|'') return 0 ;;
            *) menu_message '请选择菜单上的数字。' "${warning:-}"; continue ;;
        esac
        menu_prompt '按 Enter 返回系统安全加固' _ || return 0
    done
}

draw_menu() {
    local key notice
    key=$(get_shortcut)
    menu_title 'Hrules  协议服务管理'
    printf '  快捷启动    %s%s%s\n' "$accent" "${key:-hrules-six}" "$plain"
    if [[ -s ${state%/*}/github-update-status.json ]] &&
        notice=$(run_installer update --update-action notice 2>/dev/null) && [[ -n $notice ]]; then
        printf '  %s%s%s\n' "$title_color" "$notice" "$plain"
    fi
    if [[ -z $key && ! -e $shortcut_record && ! -L $shortcut_record ]] && shortcut_taken m; then
        printf '%s\n' '  m 已被占用，可在菜单 17 修改快捷命令。'
    fi
    printf '\n'
    menu_item 88 '重启服务器' "${warning:-}"
    menu_heading '部署与订阅'
    menu_item 1 '安装 / 更新协议服务（含节点管理）'
    menu_item 2 '服务状态与故障自查'
    menu_item 3 '订阅链接和二维码'
    menu_heading '协议与出口'
    menu_item 4 'Hysteria2 设置'
    menu_item 5 'REALITY Vision 握手网站'
    menu_item 6 '出口代理管理'
    menu_heading '流量管理'
    menu_item 7 '查看累计用量'
    menu_item 8 '修改流量上限'
    menu_item 9 '清零已用流量'
    menu_item 10 '调整采样间隔'
    menu_heading '服务控制'
    menu_item 11 '启动代理服务'
    menu_item 12 '停止代理服务'
    menu_item 13 '重启代理和订阅'
    menu_item 14 '查看最近日志'
    menu_heading '脚本管理'
    menu_item 15 '检查并更新脚本'
    menu_item 16 '脚本维护（自动更新 / 恢复 / 卸载）'
    menu_item 17 '设置快捷启动'
    menu_heading '系统工具'
    menu_item 18 'TCP / BBRv3 设置'
    menu_item 19 '系统软件包更新'
    menu_item 20 '系统安全加固'
    menu_item 21 '节点测速与基准'
    menu_item 22 '系统信息查询'
    menu_item 0 '退出'
}

menu() {
    initialize_menu_shortcut
    local choice
    while true; do
        if [[ -t 1 && ${TERM:-dumb} != dumb ]]; then
            printf '\033[H\033[2J'
        fi
        draw_menu
        menu_prompt '请选择 [0–22、88]' choice || return 0
        printf '\n'
        case $choice in
            88)
                if sudo reboot; then
                    menu_message '已提交重启请求。' "${success:-}"
                    return 0
                fi
                menu_message '提交重启请求失败，请查看上面的系统报错。' "${failure:-}" >&2
                ;;
            1) if guided_install; then continue; fi ;;
            2) run_installer diagnose ;;
            3) run_backend links ;;
            4) if guided_hysteria; then continue; fi ;;
            5) run_installer reality-vision ;;
            6) run_backend outbound ;;
            7) run_backend quota ;;
            8) ask_limit ;;
            9) ask_reset ;;
            10) ask_interval ;;
            11) backend_ready && systemctl start "$core" && show_services ;;
            12) backend_ready && systemctl stop "$core" && show_services ;;
            13) backend_ready && systemctl restart "$core" "$subscription" && show_services ;;
            14) backend_ready && journalctl -u "$core" -u "$subscription" -u hrules-six-hysteria2.service -u hrules-six-traffic.service -u hrules-six-vpngate.service --no-pager -n 60 ;;
            15) apply_menu_update apply ;;
            16) if guided_update; then continue; fi ;;
            17) ask_shortcut ;;
            18) if guided_bbr3; then continue; fi ;;
            19) run_installer system-update --yes ;;
            20) if guided_system_security; then continue; fi ;;
            21) if guided_performance; then continue; fi ;;
            22) run_installer system-info ;;
            0) return 0 ;;
            *) menu_message '请选择菜单上的数字。' "${warning:-}" ;;
        esac
        menu_prompt '按 Enter 返回菜单' _ || return 0
    done
}

online_bootstrap() {
    if [[ -f $state || -f $landing_state ]]; then
        run_installer update --update-action apply || return $?
        initialize_manager_updates
    else
        install_manager || return $?
    fi
    if [[ ${1:-} == settings ]]; then
        exec bash "$manager" update settings
    fi
    if [[ -t 0 ]]; then
        exec bash "$manager" menu
    fi
}

case ${1:-menu} in
    menu)
        if [[ ! -t 0 ]]; then usage; exit 1; fi
        menu
        ;;
    online) shift; online_bootstrap "$@" ;;
    install) shift; initialize_menu_shortcut; install_stack "$@" ;;
    landing) shift; initialize_menu_shortcut; run_installer landing "$@" ;;
    node-prefix|node-suffix) shift; edit_node_prefix "$@" ;;
    status|links|quota|traffic-interval|outbound|nodes) run_backend "$@" ;;
    bbr3|system-update|system-info|reality-vision|uninstall|diagnose|performance) run_installer "$@" ;;
    ssh-defense) shift; if (( $# )); then run_installer ssh-defense "$@"; else guided_ssh_defense; fi ;;
    firewall|firewall-ports|ssh-key|ssh-update|security-updates) run_installer "$@" ;;
    shortcut) shift; if (( $# <= 1 )); then shortcut_command "$@"; else usage; exit 2; fi ;;
    update)
        shift
        if [[ ${1:-} == settings && $# == 1 ]]; then
            initialize_menu_shortcut
            guided_auto_update
        elif (( $# )); then
            run_installer update "$@"
        else
            initialize_menu_shortcut
            guided_update
        fi
        ;;
    *) usage; exit 2 ;;
esac
exit $?
